import { z } from 'zod';

// Validator first, type derived from it. Two hand-written declarations drift;
// this pair cannot.
const checkout = z.discriminatedUnion('status', [
  z.object({ status: z.literal('pending'), expiresAt: z.string().datetime() }),
  z.object({ status: z.literal('paid'), reference: z.string().min(1) }),
  z.object({ status: z.literal('failed'), reason: z.string(), retryable: z.boolean() }),
]);

export type Checkout = z.infer<typeof checkout>;

export async function loadCheckout(id: string): Promise<Checkout> {
  const res = await fetch(`/api/checkout/${id}`);
  if (!res.ok) throw new Error(`Checkout ${id}: ${res.status}`);
  // Not `as Checkout`. A cast is a promise; this is a check.
  return checkout.parse(await res.json());
}

export function describe(c: Checkout): string {
  switch (c.status) {
    case 'pending':
      return `Awaiting payment until ${c.expiresAt}`;
    case 'paid':
      return `Paid — ${c.reference}`; // reference exists only in this branch
    case 'failed':
      return c.retryable ? `Failed: ${c.reason}. Try again.` : `Failed: ${c.reason}`;
    default: {
      // Add a fourth status and this line stops compiling, which is the point.
      const unreachable: never = c;
      return unreachable;
    }
  }
}
